for c in data.get('claims', []):
    ev = c.get('evidence', [])
    if isinstance(ev, str):
        bad.append((c['id'], ev))
    elif isinstance(ev, list):
        for item in ev:
            if not isinstance(item, str):
                bad.append((c['id'], f'non-string list item: {type(item).__name__}: {item}'))
if bad:
    print('FOUND ISSUES:')
    for cid, issue in bad:
        print(f'  {cid}: {issue}')
else:
    print('All evidence fields are properly formatted lists of strings')
print(f'Total claims: {len(data.get(\"claims\", []))}')
